const tabId = 103795220;

async function getClassesForCurrentView() {
  const snap = await browser.snapshot({ tabId });
  const lines = snap.text.split('\n');
  const classes = [];
  let currentHeading = "";
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].trim();
    if (l.includes('heading "') && (l.includes('2026') || l.includes('Monday') || l.includes('Tuesday') || l.includes('Wednesday') || l.includes('Thursday') || l.includes('Friday') || l.includes('Saturday') || l.includes('Sunday'))) {
      currentHeading = l;
    }
    if (l.startsWith('cell "') && (l.includes('AM') || l.includes('PM'))) {
      const timeCell = l;
      const classCell = lines[i+1] ? lines[i+1].trim() : "";
      classes.push({ timeCell, classCell });
    }
  }
  return { currentHeading, classes };
}

console.log("Friday:", await getClassesForCurrentView());

