const tabId = 103795220;

async function getDayClasses(ref, dayLabel) {
  await tool.element_interact({ tabId, ref, operation: "click" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2500 });
  const snap = await browser.snapshot({ tabId });
  const lines = snap.text.split('\n');
  const cellLines = lines.filter(l => l.trim().startsWith('cell "'));
  const schedule = [];
  for (let i = 0; i < cellLines.length; i += 4) {
    schedule.push({
      timeLoc: cellLines[i]?.replace(/.*cell "/, '').replace(/" \[ref=.*/, ''),
      classInstructor: cellLines[i+1]?.replace(/.*cell "/, '').replace(/" \[ref=.*/, ''),
      status: cellLines[i+2]?.replace(/.*cell "/, '').replace(/" \[ref=.*/, '')
    });
  }
  return { dayLabel, schedule };
}

